contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: from invokes transfer by calling c.transfer from this contract's address.
    // We will simulate different recipients and amounts by first arranging balances via mintToken (owner-only),
    // but since InvMutTest is NOT the owner of c, we must rely on initial allocation: the deployer of c is owner,
    // and the checker deploys a fresh c and then deploys this test with that c, so this contract is NOT owner.
    // Therefore, to make meaningful transfers, we will use the existing balances: address(this) (the test) may have zero balance in c.
    // To ensure address(this) has tokens, we rely on the fact that the checker deploys c then deploys InvMutTest passing c; the deployer of c is owner, which is a distinct address.
    // However we cannot call owner-only methods. So instead we will use the property that transfer preserves combined balance for any two addresses regardless of their absolute balances as long as transfer succeeds.

    // We take as parameters the recipient and amount to attempt transferring from this contract's c-balance to recipient.
    function run(address to, uint256 amount) public payable {
        require(to != address(0)); // _transfer disallows zero address; we restrict inputs so that when transfer succeeds it obeys invariant

        // Read balances before
        uint256 balFrom_before = c.balanceOf(address(this));
        uint256 balTo_before = c.balanceOf(to);

        // Attempt transfer and record whether it reverted
        bool reverted;
        try c.transfer{value: 0}(to, amount) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after
        uint256 balFrom_after = c.balanceOf(address(this));
        uint256 balTo_after = c.balanceOf(to);

        // The general rule: if the transfer call did NOT revert, then (balFrom_after + balTo_after) == (balFrom_before + balTo_before)
        // If it reverted, no state change is guaranteed; so we only assert the preservation when not reverted.
        assert(reverted || (balFrom_after + balTo_after == balFrom_before + balTo_before));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public payable {
        require(to != address(0));

        uint256 balFrom_before = c.balanceOf(address(this));
        uint256 balTo_before = c.balanceOf(to);

        bool reverted;
        try c.transfer(to, amount) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balFrom_after = c.balanceOf(address(this));
        uint256 balTo_after = c.balanceOf(to);

        assert(reverted || (balFrom_after + balTo_after == balFrom_before + balTo_before));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = msg.sender;
    }

    // single public test function taking inputs: target address and desired freeze flag
    function run(address target, bool freeze) public payable {
        require(address(this) != address(0)); // trivial sanity so params used

        // Observe owner and frozen status before any calls
        address ownerBefore = c.owner();
        bool frozenBefore = c.frozenAccount(target);

        // Attempt call as non-owner: since this contract is the deployer of c, msg.sender for c calls will be this contract.
        // To simulate a non-owner caller we need to call freezeAccount from this contract when this contract is not the owner.
        // If this contract is the owner, first transfer ownership-like control cannot be done (no setter), so we detect both cases.

        bool nonOwnerReverted;
        // If this contract is owner, then calling freezeAccount should succeed; otherwise it should revert.
        // Try call and record whether it reverted.
        try c.freezeAccount(target, freeze) {
            nonOwnerReverted = false;
        } catch {
            nonOwnerReverted = true;
        }

        // Read frozen status after attempted call
        bool frozenAfter = c.frozenAccount(target);
        address ownerAfter = c.owner();

        // Assert general rule: if this contract is not the owner, call must revert and frozen flag unchanged;
        // if this contract is the owner, call must not revert and frozen flag equals the requested value.
        assert(
            (ownerBefore != address(this) && nonOwnerReverted && frozenAfter == frozenBefore && ownerAfter == ownerBefore)
            ||
            (ownerBefore == address(this) && !nonOwnerReverted && frozenAfter == freeze && ownerAfter == ownerBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that tries burning and asserts owner-only behavior and supply/balance invariants
    function run(address target, uint256 burnAmount) public payable {
        require(address(this) != address(0)); // trivial sanity, not about c

        // observe before-values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(address(this));
        address owner = c.owner();

        // attempt burn as this contract (msg.sender for c calls will be this contract)
        bool reverted;
        try c.burn(burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(address(this));

        // If burn succeeded then this contract must be owner and both totalSupply and caller balance decreased by burnAmount
        assert(reverted || (owner == address(this) && afterTotal + burnAmount == beforeTotal && afterBalance + burnAmount == beforeBalance));
    }

    // allow receiving ether if needed elsewhere
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 mintedAmount) public payable {
        // record before-values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalTarget = c.balanceOf(target);

        // attempt mint and observe revert
        bool reverted;
        try c.mintToken(target, mintedAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalTarget = c.balanceOf(target);

        // If mint succeeded then totalSupply and target balance must each increase by mintedAmount.
        // If mint reverted then caller (this contract) must not be owner. We observe owner via public getter.
        address owner = c.owner();
        bool callerIsOwner = (owner == address(this));

        assert(
            (!reverted && afterTotal == beforeTotal + mintedAmount && afterBalTarget == beforeBalTarget + mintedAmount)
            || (reverted && !callerIsOwner)
        );
    }
    receive() external payable { }
}
